// People and the weekly contest, as data: site/contributors/<id>.json (the owner, the house
// personas and the team's AI agents) and site/contest/weeks/<YYYY-Www>.json (one per ISO week,
// generated by the engine's `fe content contest`). Checked here, so a bad file fails the build, and rendered by
// site/pages/people.mjs and site/pages/contest.mjs. Avatars are 2–3 frames of 32 × 32 letter grids
// (`avatars`; the first is the still one) drawn with avatar tokens only (AVATAR_PALETTE: site.css
// --av-*, each a Board UI token or a mix of two), one <path> per color.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { MICRO_CAP, contributors as galleryContributors, laneOf } from "./gallery.mjs";

const WEEKS = "site/contest/weeks";
const NEED = ["id", "name", "role", "bio", "description", "kind", "style", "hobbies", "favoriteGames", "avatars"];
/** The studio crew line (kind "persona"): its sticker's accessible name and its profile's structured data. */
export const PERSONA_NOTE = "Studio crew — a Fizlet character, not a real person";
/** The AI agent line: every agent's card and page says it, word for word. */
export const AGENT_NOTE = "AI agent — an AI agent persona on the Fizlet team, not a real person";
/** What each kind is called on the site (the data key stays `kind`). */
export const KIND_LABEL = { owner: "Maker", agent: "AI agent", persona: "Studio crew" };
/**
 * The sticker on every avatar's corner: its text, and the accessible name that keeps it honest
 * (aria-label and title): agents and crew say they are not real people.
 */
export const STICKER = {
  owner: { text: "MAKER", label: "Maker: the real person who builds Fizlet" },
  agent: { text: "AI AGENT", label: "AI agent: an AI agent persona, not a real person" },
  persona: { text: "CHARACTER", label: "Character: a Fizlet character, not a real person" },
};
/** Contributor kinds, in page order: the one owner, the team's AI agents, the house personas. */
export const KINDS = ["owner", "agent", "persona"];
/**
 * Contest rules the data must keep (and Daily and the contest page state, from here). Each day takes
 * up to `perDay` entries; the voters pick the day's top `picks[0]` to `picks[1]`; the picks are all
 * posted at the end of the week, then one weekly winner and one monthly winner are picked. When a day
 * has too few entries, the team backfills it with its own pieces. Two lanes (owner, 2026-11-13):
 * the micro contest, where size decides, not the prompt: a piece whose live chunk (gzip bytes,
 * measured at build: its size badge) is at most `maxLive` can win; and Hi-Fi (`"lane": "hifi"` on
 * the entry: dioramas, 2.5D, full mini-games, heroes over the cap), whose pieces compete only with
 * each other for their own weekly winner (`hifiWinner`). A piece over the cap is Hi-Fi (the
 * gallery build fails otherwise). 10,240 B is the budget a hero's live chunk already has
 * (scripts/sizes.mjs, page build: bricks ≤ 7 KB + scene ≥ 3 KB). `voters`: contributor ids
 * (site/contributors), in the order named.
 */
export const CONTEST = { maxLive: MICRO_CAP, perDay: 40, picks: [1, 5], voters: ["frame-zero", "dj-mempool", "hex-hazel", "quill", "pip", "chris-cooley"] };
/** Whether a measured gallery entry can win a micro week: a micro, its live bytes at or under the cap. */
export const canWin = (e) => laneOf(e) === "micro" && e.size <= CONTEST.maxLive;
/** Whether a gallery entry is in the Hi-Fi lane (it can win only the week's Hi-Fi award). */
export const isHifi = (e) => laneOf(e) === "hifi";

const DAY = 86400000;
/** The ISO 8601 week of a date (UTC): "2026-10-31" → "2026-W44". */
export function isoWeek(date) {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7) + 3); // that week's Thursday names the year
  const year = d.getUTCFullYear(), jan4 = Date.UTC(year, 0, 4);
  const week = 1 + Math.round((d - jan4 - (3 - ((new Date(jan4).getUTCDay() + 6) % 7)) * DAY) / (7 * DAY));
  return `${year}-W${String(week).padStart(2, "0")}`;
}
/** The seven dates of an ISO week, Monday first. */
export function weekDates(week) {
  const [y, w] = week.split("-W").map(Number), jan4 = Date.UTC(y, 0, 4);
  const monday = jan4 - ((new Date(jan4).getUTCDay() + 6) % 7) * DAY + (w - 1) * 7 * DAY;
  return Array.from({ length: 7 }, (_, i) => new Date(monday + i * DAY).toISOString().slice(0, 10));
}

/**
 * Avatar letters → avatar tokens (site/site.css --av-*: a fixed Board UI color or a mix of two, so a
 * sprite reads the same in both themes). Ramps run light, base, shadow: w e f white, C c s cyan,
 * P p q purple, R r d red, M m n magenta, O o u orange, Y y t yellow, L l j lime, G g h mint;
 * a i jersey black, k the rim outline, b a glow; "." is the dark ground (--av-bg).
 */
export const AVATAR_PALETTE = Object.fromEntries([..."kwefCcsPpqRrdMmnOouYytLljGghaib"].map((ch) => [ch, `--av-${ch}`]));

const read = (dir) => (existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith(".json")).sort() : [])
  .map((f) => ({ f, v: JSON.parse(readFileSync(`${dir}/${f}`, "utf8")) }));

/** A gallery entry's author id (a site/contributors/<id>.json). */
export const authorOf = (e) => e.author;

/** The contributors (scripts/gallery.mjs reads them), checked for a profile: the owner first, then the agents, then the personas, each by name. */
export function contributors(dir) {
  const list = Object.values(galleryContributors(dir)).map((p) => {
    const f = `${p.id}.json`;
    for (const k of NEED) if (p[k] === undefined) throw new Error(`contributors/${f}: missing ${k}`);
    if (!KINDS.includes(p.kind)) throw new Error(`contributors/${f}: kind ${p.kind}`);
    if (p.kind !== "owner" && (p.url || !p.handle)) throw new Error(`contributors/${f}: ${p.kind === "agent" ? "an agent" : "a persona"} has a handle and no url (no fake links)`);
    if (p.pronouns !== undefined) throw new Error(`contributors/${f}: no pronouns or gender on the public site (owner, 2026-11-02)`);
    if (!Array.isArray(p.avatars) || p.avatars.length < 2 || p.avatars.length > 3) throw new Error(`contributors/${f}: avatars is 2 or 3 frames`);
    p.avatars.forEach((a, i) => checkAvatar(a, `contributors/${f} avatars[${i}]`));
    if (p.tagline !== undefined && (typeof p.tagline !== "string" || !p.tagline)) throw new Error(`contributors/${f}: tagline is a string`);
    return p;
  });
  if (list.filter((p) => p.kind === "owner").length !== 1) throw new Error("contributors: exactly one owner");
  const ids = new Set(list.map((p) => p.id));
  for (const p of list) {
    if (p.kind === "owner" ? p.reportsTo !== undefined : !ids.has(p.reportsTo) || p.reportsTo === p.id) throw new Error(`contributors/${p.id}.json: reportsTo ${p.reportsTo ?? "is missing"}`);
  }
  return list.sort((a, b) => KINDS.indexOf(a.kind) - KINDS.indexOf(b.kind) || a.name.localeCompare(b.name));
}

function checkAvatar(rows, where) {
  if (!Array.isArray(rows) || rows.length !== 32) throw new Error(`${where}: avatar is 32 rows`);
  for (const r of rows) {
    if (r.length !== 32) throw new Error(`${where}: avatar rows are 32 pixels`);
    for (const ch of r) if (ch !== "." && !AVATAR_PALETTE[ch]) throw new Error(`${where}: avatar color "${ch}" is not a token`);
  }
}

/**
 * The avatar as inline SVG: a token background, then one path per color (runs of a row as
 * `M x y h n v1 h-n z`). Crisp at any size: shape-rendering crispEdges, image-rendering pixelated.
 * `label`: its accessible name, or null for a decorative copy (aria-hidden). `cls`: extra classes.
 */
export function avatarSvg(rows, { size = 64, label = null, cls = "" } = {}) {
  const paths = {};
  rows.forEach((row, y) => {
    for (let x = 0; x < 32;) {
      const ch = row[x];
      let n = 1;
      while (x + n < 32 && row[x + n] === ch) n++;
      if (ch !== ".") paths[ch] = (paths[ch] ?? "") + `M${x} ${y}h${n}v1h-${n}z`;
      x += n;
    }
  });
  const a11y = label ? `role="img" aria-label="${label.replace(/&/g, "&amp;").replace(/"/g, "&quot;")}"` : 'aria-hidden="true"';
  return `<svg class="ppl-av${cls ? ` ${cls}` : ""}" viewBox="0 0 32 32" width="${size}" height="${size}" ${a11y} shape-rendering="crispEdges"><rect width="32" height="32" fill="var(--av-bg)"/>` +
    Object.entries(paths).map(([ch, d]) => `<path fill="var(${AVATAR_PALETTE[ch]})" d="${d}"/>`).join("") + "</svg>";
}

/**
 * The contest weeks, checked against the gallery, oldest first. A week's entries are its dailies:
 * the live gallery entries dated inside it (measured: `size` is set by the gallery build), smallest
 * first; archived entries (site/gallery/archive) are never entries. Its winner is one of them, only
 * on a closed week, a micro and never one over the size cap (CONTEST.maxLive); its `hifiWinner`
 * (optional) is one of its Hi-Fi entries, also only on a closed week. Each week also gets `micro`
 * and `hifi` (its entries by lane), `smallest` (the id of its smallest entry that can win, or null)
 * and `dates` (Monday to Sunday).
 * The old per-day `contest` stamp on an entry fails the build. `files`: [{ f, v }] (file name,
 * parsed JSON), read from site/contest/weeks by default.
 */
export function contestWeeks(gallery, people, files = read(WEEKS)) {
  const ids = new Set(people.map((p) => p.id));
  for (const e of gallery) {
    const a = authorOf(e);
    if (a && !ids.has(a)) throw new Error(`gallery/${e.id}: author ${a} has no site/contributors/${a}.json`);
    if (e.contest !== undefined) throw new Error(`gallery/${e.id}: "contest" is gone: a week's entries are its dailies (drop it)`);
  }
  const weeks = files.map(({ f, v: w }) => {
    const at = `contest/weeks/${f}`;
    for (const k of ["week", "theme", "brief", "status"]) if (w[k] === undefined) throw new Error(`${at}: missing ${k}`);
    if (`${w.week}.json` !== f || !/^\d{4}-W\d{2}$/.test(w.week) || isoWeek(weekDates(w.week)[0]) !== w.week) throw new Error(`${at}: week ${w.week}`);
    if (!["upcoming", "open", "judging", "closed"].includes(w.status)) throw new Error(`${at}: status ${w.status}`);
    const entries = gallery.filter((e) => !e.archived && isoWeek(e.date) === w.week);
    for (const e of entries) if (!Number.isInteger(e.size)) throw new Error(`gallery/${e.id}: a contest entry is measured first (no size)`);
    entries.sort((a, b) => a.size - b.size || a.id.localeCompare(b.id));
    const micro = entries.filter((e) => !isHifi(e)), hifi = entries.filter(isHifi);
    const week = { hifiWinner: null, ...w, dates: weekDates(w.week), entries, micro, hifi, smallest: micro.find(canWin)?.id ?? null };
    const pick = (key, lane) => {
      const win = entries.find((e) => e.id === w[key]);
      if (!win) throw new Error(`${at}: ${key} ${w[key]} is not one of its dailies (${entries.map((e) => e.id).join(", ") || "none"})`);
      if (w.status !== "closed") throw new Error(`${at}: a winner is set only once the week is closed`);
      if (laneOf(win) !== lane) throw new Error(`${at}: ${key} ${win.id} is ${lane === "hifi" ? "a micro: it competes for the micro winner (winner)" : "a Hi-Fi piece: it competes only in the Hi-Fi lane (hifiWinner)"}`);
      return win;
    };
    if (w.winner && !canWin(pick("winner", "micro"))) throw new Error(`${at}: winner ${w.winner} is too big to win (${entries.find((e) => e.id === w.winner).size} B live, the cap is ${CONTEST.maxLive} B)`);
    if (w.hifiWinner) pick("hifiWinner", "hifi");
    return week;
  });
  return weeks.sort((a, b) => a.week.localeCompare(b.week));
}

/** The week the contest page leads with: this week's, else the next one, else the latest. */
export function contestNow(weeks, today = new Date().toISOString().slice(0, 10)) {
  const now = isoWeek(today);
  return weeks.find((w) => w.week === now) ?? weeks.find((w) => w.week > now) ?? weeks[weeks.length - 1] ?? null;
}

/** A contributor's gallery entries (newest first, as the gallery orders them) and their measured bytes. */
export function statsOf(person, gallery) {
  const entries = gallery.filter((e) => authorOf(e) === person.id);
  return { entries, count: entries.length, bytes: entries.reduce((n, e) => n + e.size, 0) };
}
